import figma from "figma";

const instance = figma.selectedInstance;

const textOf = (node) =>
  node && node.type === "TEXT" ? node.textContent : undefined;

const name = instance.getString("Name");
const error = textOf(instance.findText("Error"));

export default {
  id: "File",
  example: instance.getEnum("Status", {
    uploading: figma.code`<HvFile data={{ id: "file", name: "${name ?? ""}", status: "progress" }} />`,
    success: figma.code`<HvFile data={{ id: "file", name: "${name ?? ""}", status: "success" }} />`,
    error: figma.code`<HvFile data={{ id: "file", name: "${name ?? ""}", status: "fail", errorMessage: "${error ?? ""}" }} />`,
  }),
  imports: ['import { HvFile } from "@pentaho/uikit-react-core";'],
  metadata: { nestable: true },
};
